function norm(s) {
  return String(s || '').toLowerCase().replace(/【[^】]*】/g, '').replace(/\[[^\]]*\]/g, '').replace(/\([^)]*\)/g, '').replace(/（[^）]*）/g, '').replace(/\s+/g, '').trim();
}
function req(method, p, body) {
  return new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : null;
    const h = { 'X-API-Key': KEY, 'Content-Type': 'application/json' };
    if (data) h['Content-Length'] = Buffer.byteLength(data);
    const r = http.request({ host: '127.0.0.1', port: 8760, path: p, method, headers: h }, (res) => {
      let d = ''; res.on('data', (c) => (d += c)); res.on('end', () => resolve({ code: res.statusCode, body: d }));
    });
    r.on('error', reject);
    if (data) r.write(data);
    r.end();
  });
}
async function main() {
  const list = await req('GET', '/api/models?brand=%E5%8D%8E%E4%B8%BA&limit=500');
  const items = JSON.parse(list.body).items;
  let done = 0, skip = 0;
  const skipped = [];
  for (const it of items) {
    const n = norm(it.model);
    let bestKey = null, bestLen = 0;
    for (const key of Object.keys(SPECS)) {
      if (n === key) { bestKey = key; break; }
      if (n.startsWith(key) && key.length > bestLen) { bestLen = key.length; bestKey = key; }
    }
    if (!bestKey) { skip++; skipped.push(it.model); continue; }
    const r = await req('PUT', '/api/models/' + it.id, SPECS[bestKey]);
    if (r.code === 200) done++; else console.log('[FAIL]', it.model, r.code);
  }
  console.log('华为规格(Mate/P/Pocket)写入:', done, '条, 跳过', skip);
  console.log('待下批覆盖:', skipped.join(' | '));
}
main().catch((e) => { console.error('ERR', e); process.exit(1); });
